function handleCellInput(e) {
    const cellElement = e.currentTarget;
    let rawValue = e.target.innerText.trim();
    const key = getCellKey(cellElement.dataset.col, cellElement.dataset.row);

    // 1. Update State
    spreadsheetData[key].rawInput = rawValue;
    spreadsheetData[key].isFormula = rawValue.startsWith('=');

    // 2. Calculate and Set Value (This handles the immediate display update)
    calculateAndSetCell(key);

    // 3. Trigger Recalculation for dependent cells
    triggerRecalculation(key);
}
