/**
 * Converts a column index (0-based) to its letter representation (A, B, C...).
 * @param {number} index - The 0-based index of the column.
 * @returns {string} The corresponding column letter.
 */
function colIndexToLetter(index) {
    let temp = index;
    let letters = '';
    while (temp >= 0) {
        letters = String.fromCharCode((temp % 26) + 65) + letters;
        temp = Math.floor(temp / 26) - 1;
    }
    return letters;
}

