function handleCellInput(e) {
    const cell = e.target;
    if (!cell || !cell.dataset.col || !cell.dataset.row) return;

    // 1. Update the internal state immediately
    const key = getCellKey(parseInt(cell.dataset.col), parseInt(cell.dataset.row));
    let value = cell.innerText.trim();

    if (value === "") {
        // If empty, treat it as null/empty string for storage
        saveState(key, "");
    } else if (!isNaN(parseFloat(value)) && isFinite(value) && !cell.dataset.formula) {
        // Check if the input looks like a number and isn't explicitly marked as formula (though formulas are usually handled by calculation)
        // For simplicity in this fix, we just save the text content unless it's empty.
        saveState(key, value);
    } else {
        saveState(key, value);
    }

    // 2. Trigger recalculation for dependent cells
    triggerRecalculation(key);

    // 3. Clean up UI state (remove active edit class)
    cell.classList.remove('active-edit');
    cell.contentEditable = 'false';
    selectCell(cell); // Re-select to keep focus visual feedback if needed, or just leave it clean.
}
